CREATE POLICY "Admins can read ebook files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'ebook-files' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can upload ebook files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'ebook-files' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can update ebook files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'ebook-files' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can delete ebook files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'ebook-files' AND public.has_role(auth.uid(), 'admin'));